const readEnv = (name) => {
  try {
    const v = process?.env?.[name];
    return typeof v === 'string' && v.trim() ? v.trim() : '';
  } catch { return ''; }
};
const bufferFolderId = readEnv('SIGA_TELEGRAM_BUFFER_FOLDER_ID') || '1tbyhFwLBWm5jh605vngOqpHN-Gpb-9yf';
const webhookUrl = readEnv('SIGA_MAIN_WEBHOOK_URL') || 'https://n8n.srv961978.hstgr.cloud/webhook/siga-ingestion-v1';
const sharedSecret = readEnv('SIGA_WEBHOOK_SECRET') || readEnv('SIGA_SHARED_SECRET') || readEnv('N8N_SIGA_WEBHOOK_SECRET') || readEnv('N8N_SIGA_SHARED_SECRET') || '';
return [{
  json: {
    now: new Date().toISOString(),
    buffer_folder_id: bufferFolderId,
    buffer_folder_path: 'SIGA_TEMP/SIGA_TELEGRAM_BUFFER',
    main_webhook_url: webhookUrl,
    shared_secret: sharedSecret,
    quiet_window_sec_default: 5,
    processor_source: 'telegram_buffer_batch'
  }
}];

const root = $('Init Processor Config').first().json || {};
const files = Array.isArray($json.files) ? [...$json.files] : [];
const partFiles = files.filter(f => /__part_\d+\.json$/i.test(String(f.name || '')));
const processedFiles = files.filter(f => /__processed\.json$/i.test(String(f.name || '')));
return [{
  json: {
    ...root,
    all_json_files: files,
    part_json_files: partFiles,
    processed_marker_files: processedFiles,
    part_json_count: partFiles.length
  }
}];

const root = $json;
const parts = Array.isArray(root.part_json_files) ? root.part_json_files : [];
return parts.map(f => ({
  json: {
    ...root,
    part_json_file_id: f.id,
    part_json_name: f.name,
    part_json_createdTime: f.createdTime || null,
    part_json_webViewLink: f.webViewLink || null
  }
}));

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  let txt = '';
  try {
    const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    txt = Buffer.from(buf).toString('utf8');
  } catch (e) {
    const raw = item.binary?.data?.data;
    if (Buffer.isBuffer(raw)) {
      txt = raw.toString('utf8');
    } else if (typeof raw === 'string' && raw) {
      txt = Buffer.from(raw, 'base64').toString('utf8');
    }
  }
  txt = String(txt || '').replace(/^\uFEFF/, '').trim();
  const parsed = JSON.parse(txt);
  out.push({
    json: {
      ...item.json,
      part: parsed,
      buffer_prefix: parsed.buffer_prefix || item.json.buffer_prefix || '',
      group_key: parsed.group_key || '',
      media_group_id: parsed.media_group_id || null,
      message_id: parsed.message_id || null,
      quiet_until: parsed.quiet_until || null
    }
  });
}
return out;

const now = Date.now();
const items = $input.all().map(i => i.json || {});
const groups = new Map();

const firstNonEmpty = (arr, getter) => {
  for (const x of arr) {
    const v = getter(x);
    if (v !== null && v !== undefined && v !== '') return v;
  }
  return null;
};

for (const j of items) {
  const prefix = j.buffer_prefix || '';
  if (!prefix) continue;
  const g = groups.get(prefix) || { parts: [], root: j, lastQuietUntil: 0, firstSeen: Number.MAX_SAFE_INTEGER };
  const part = j.part || j;
  g.parts.push(part);
  const q = Date.parse(j.quiet_until || part.quiet_until || '') || 0;
  const seen = Date.parse(part.message_received_at || j.message_received_at || '') || now;
  if (q > g.lastQuietUntil) g.lastQuietUntil = q;
  if (seen < g.firstSeen) g.firstSeen = seen;
  if ((part.message_text || part.caption_text || part.text) && !(g.root.message_text || g.root.part?.message_text || g.root.caption_text || g.root.part?.caption_text || g.root.text || g.root.part?.text)) {
    g.root = j;
  }
  groups.set(prefix, g);
}

const ready = [...groups.values()]
  .filter(g => g.lastQuietUntil > 0 && g.lastQuietUntil <= now)
  .sort((a, b) => a.firstSeen - b.firstSeen);

if (!ready.length) return [{ json: { ready_group_found: false, reason: 'no_ready_group' } }];

const g = ready[0];
const parts = [...g.parts].sort((a, b) => Number(a.message_id || 0) - Number(b.message_id || 0));
const sender = firstNonEmpty(parts, p => p.sender) || {};
const chatId = firstNonEmpty(parts, p => p.chat_id);
const chatType = firstNonEmpty(parts, p => p.chat_type);
const mediaGroupId = firstNonEmpty(parts, p => p.media_group_id) || g.root.media_group_id || null;
const msgText =
  firstNonEmpty(parts, p => p.message_text) ||
  firstNonEmpty(parts, p => p.caption_text) ||
  firstNonEmpty(parts, p => p.text) ||
  '';
const markerName = `${g.root.buffer_prefix}processed.json`;

return [{
  json: {
    ...$('Init Processor Config').first().json,
    ready_group_found: true,
    buffer_prefix: g.root.buffer_prefix,
    group_key: g.root.group_key,
    media_group_id: mediaGroupId,
    chat_id: chatId,
    chat_type: chatType,
    sender,
    message_text: msgText,
    quiet_until: new Date(g.lastQuietUntil).toISOString(),
    group_parts: parts,
    processed_marker_name: markerName
  }
}];

const root = $json;
const files = Array.isArray(root.files) ? root.files : [];
const parts = Array.isArray(root.group_parts) ? root.group_parts : [];
const byName = new Map(files.map(f => [String(f.name || ''), f]));
const orderedParts = [...parts].sort((a, b) => Number(a.message_id || 0) - Number(b.message_id || 0));
const mediaItems = [];

for (const p of orderedParts) {
  const name = p.buffer_file_name;
  if (!name) continue;
  const f = byName.get(String(name));
  if (!f) continue;
  const mime = String(p.mime_type || f.mimeType || 'application/octet-stream').toLowerCase();
  mediaItems.push({
    ...root,
    part: p,
    drive_file_id: f.id,
    drive_file_name: f.name,
    drive_mime_type: f.mimeType || p.mime_type || 'application/octet-stream',
    media_kind: mime.startsWith('image/') ? 'image' : 'document',
    media_order: Number(p.message_id || mediaItems.length + 1)
  });
}

return mediaItems;

const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const p = item.json.part || {};
  let b64 = '';

  try {
    const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    b64 = buf.toString('base64');
  } catch (e) {
    b64 = item.binary?.data?.data || '';
  }

  const mime = String(p.mime_type || item.json.drive_mime_type || 'application/octet-stream').toLowerCase();
  const row = {
    index: i + 1,
    order: Number(item.json.media_order || p.message_id || i + 1),
    filename: p.original_filename || item.json.drive_file_name || ('file_' + (i + 1)),
    mime_type: p.mime_type || item.json.drive_mime_type || 'application/octet-stream',
    content_base64: b64,
    source_file_name: item.json.drive_file_name || p.buffer_file_name || null,
    telegram_message_id: p.message_id || null
  };

  out.push({
    json: {
      ...item.json,
      image_row: mime.startsWith('image/') ? row : null,
      document_row: mime.startsWith('image/') ? null : row
    }
  });
}

return out;

const items = $input.all().map(i => i.json || {});
if (!items.length) return [{ json: { payload_ready: false, reason: 'no_media_rows' } }];

const root = items[0];
const images = items
  .map(i => i.image_row)
  .filter(Boolean)
  .sort((a, b) => Number(a.order || a.index || 0) - Number(b.order || b.index || 0))
  .map((row, idx) => ({
    index: idx + 1,
    filename: row.filename,
    mime_type: row.mime_type,
    content_base64: row.content_base64
  }));

const documents = items
  .map(i => i.document_row)
  .filter(Boolean)
  .sort((a, b) => Number(a.order || a.index || 0) - Number(b.order || b.index || 0))
  .map(row => ({
    filename: row.filename,
    mime_type: row.mime_type,
    content_base64: row.content_base64
  }));

const sender = root.sender || {};
const payload = {
  source: 'telegram_buffered',
  project: 'SIGA',
  entity_type: 'equipment',
  sender: {
    id: sender.id || null,
    display_name: sender.first_name || sender.username || sender.display_name || null
  },
  message: {
    id: root.group_key || null,
    text: root.message_text || '',
    received_at: new Date().toISOString()
  },
  message_text: root.message_text || '',
  context: {
    telegram: {
      chat_id: root.chat_id ?? null,
      chat_type: root.chat_type ?? null,
      media_group_id: root.media_group_id || null,
      group_key: root.group_key || null,
      buffer_prefix: root.buffer_prefix || null,
      buffer_folder_id: root.buffer_folder_id || null
    }
  },
  images,
  documents
};

return [{
  json: {
    ...root,
    payload_ready: (images.length + documents.length) > 0,
    payload,
    image_count: images.length,
    document_count: documents.length
  }
}];

const j = $json;
const marker = {
  group_key: j.group_key || null,
  buffer_prefix: j.buffer_prefix || null,
  processed_at: new Date().toISOString(),
  main_webhook_url: j.main_webhook_url || null,
  image_count: j.image_count || 0,
  handoff_status: 'sent',
  handoff_response: j
};
const txt = JSON.stringify(marker, null, 2);
return [{
  json: {
    ...j,
    marker_name: j.processed_marker_name
  },
  binary: {
    data: {
      data: Buffer.from(txt, 'utf8').toString('base64'),
      mimeType: 'application/json',
      fileName: j.processed_marker_name
    }
  }
}];

const marker = $json || {};
const root = $('If Ready Group Found').first().json || {};
return [{
  json: {
    ...root,
    processed_marker_files: Array.isArray(marker.files) ? marker.files : [],
    processed_marker_found: Array.isArray(marker.files) && marker.files.length > 0
  }
}];
